struct  two_image image_data;
//定义变量
#define GraScale 256// 灰度等级数
#define grascale 256
uint16 hist[GraScale]={0};//灰度像素点的数量
float P[GraScale]={0};//每个灰度级出现的概率
float PK[GraScale]={0};//概率累计和
float MK[GraScale] = {0};//灰度值累加均值
uint8 img_threshold;//输出阈值
float imgsize;//图像像素总量
uint8 OSTU(uint8 index[60][94])
{
    uint8 threshold;
    image_data.image_size=60*94;//获取尺寸
    uint8 images_value_temp;//中间变量存储

    float sumPK = 0;
    float sumMK = 0;
    float var=0;
    float vartmp=0;

    for(uint16 i =0;i<GraScale;i++)
    {
        hist[i]=0;
        P[i]=0;
        PK[i]=0;//概率累计和
        MK[i]=0;//灰度值累加均值

    }
    //获取直方图
    for(uint8 i=0;i<60;i++)
    {
        for(uint8 j=0;j<94;j++)
        {
            images_value_temp = index[i][j];
            hist[images_value_temp]++;



        }

    }
    for(uint16 i=0;i<GraScale;i++)
    {
        P[i]=(float)hist[i]/image_data.image_size;//计算每个灰度出现的概率
        PK[i]=sumPK+P[i];//概率累计和
        sumPK=PK[i];
        MK[i]=sumMK+i*P[i];//灰度值累加均值
        sumMK=MK[i];


    }
    for(uint8 i =5;i<245;i++)
    {
        vartmp=((MK[GraScale-1]*PK[i]-MK[i])*(MK[GraScale-1]*PK[i]-MK[i]))/(PK[i]*(1-PK[i]));
        if(vartmp>var)
        {
            var=vartmp;
            threshold = i;//输出阈值

        }


    }
    return threshold;
}

/*
 * 冒泡排序
 *
 */
uint8_t bubble_sort_num[4];
void bubble_sort(void) {

    bubble_sort_num[0]=image_data.twoimg_threshold_1;
    bubble_sort_num[1]=image_data.twoimg_threshold_2;
    bubble_sort_num[2]=image_data.twoimg_threshold_3;
    bubble_sort_num[3]=image_data.twoimg_threshold_4;

    uint8_t temp;  // 用于交换的临时变量（建议命名为temp更清晰，min易混淆）
    uint8_t n = 4; // 元素个数

    // 外层循环：控制排序轮次（共需要n-1轮）
    for (uint8_t i = 0; i < n - 1; i++) {
        // 内层循环：每轮比较到未排序的最后一个元素
        // 每轮结束后，最大的元素会"冒泡"到数组末尾，因此下一轮可减少一次比较
        for (uint8_t j = 0; j < n - 1 - i; j++) {
            // 若前一个元素 < 后一个元素，交换它们（实现从大到小排序）
            if (bubble_sort_num[j] < bubble_sort_num[j + 1]) {
                temp = bubble_sort_num[j];
                bubble_sort_num[j] = bubble_sort_num[j + 1];
                bubble_sort_num[j + 1] = temp;
            }
        }
    }

// 四个阈值从小到大排序后：num[0] 最小阈值，num[1]、num[2]、num[3] 依次增大

}

// 拆分函数：将原始数组划分为4个子数组
void split_image(void) {
    // 遍历原始数组的所有像素，分配到对应的子数组
    for (int i = 0; i < 120; i++) {       // 行索引（0~119）
        for (int j = 0; j < 188; j++) {   // 列索引（0~187）
            uint8_t pixel = base_image[i][j];  // 当前像素值

            // 计算子数组的行索引（子数组行范围：0~59）
            int sub_row = i % 60;  // 0~59行 → 0~59；60~119行 → 0~59

            if (i < 60) {  // 上半部分（0~59行）
                if (j < 94) {  // 左半部分（0~93列）→ 子数组sub3
                    image_data.image_1[sub_row][j] = pixel;
                } else {  // 右半部分（94~187列）→ 子数组sub4（列索引转换为0~93）
                    image_data.image_2[sub_row][j - 94] = pixel;
                }
            } else {  // 右半部分（94~187列）→ 子数组sub4（列索引转换为0~93）
                if (j < 94) {  // 左半部分（0~93列）→ 子数组sub3
                    image_data.image_3[sub_row][j] = pixel;
                } else {  // 右半部分（94~187列）→ 子数组sub4（列索引转换为0~93）
                    image_data.image_4[sub_row][j - 94] = pixel;
                }
            }
        }
    }
}
