/*
 * 直接从 mt9v03x_image 做二值化（无逆透视），结果存入 image_two_value
 * th_0_20 / th_20_60 / th_60_120：对应行区阈值（远反光强宜偏高，近反光弱宜偏低）
 */
uint8 image_two_value[MT9V03X_H][MT9V03X_W];  // 二值化正常图像

void image_binary_forward(uint8 th_0_20, uint8 th_20_60, uint8 th_60_120)
{
    uint8 i;
    uint16 j;
    const uint8 *src;
    uint8 *dst;
    uint8 th;

    for(i = 0; i < MT9V03X_H; i++)
    {
        if(i < 20)
        {
            th = th_0_20;
        }
        else if(i < 60)
        {
            th = th_20_60;
        }
        else
        {
            th = th_60_120;
        }

        src = mt9v03x_image[i];
        dst = image_two_value[i];
        for(j = 0; j < MT9V03X_W; j++)
        {
            dst[j] = src[j] > th ? 255 : 0;
        }
    }
}
